"""Offline original-table preview of the decoded candidate, without game input."""
from pathlib import Path
import sys,json,io,base64
import numpy as np
from PIL import Image
D=Path(__file__).resolve().parent;ROOT=D.parents[3];sys.path[:0]=[str(D),str(D.parent/'native_restore')]
from preview_restore import Archive,sha,digest,need,write
def main():
 p=json.loads((D/'inputs.json').read_text('utf8'));a=Archive((ROOT/p['parent_arc']).read_bytes());b=Archive((D/'packed_dash_candidate_v1/PL00_U.ARC').read_bytes());o=D/'native_cycle_v1';need(not o.exists(),'Fresh');o.mkdir();data={};proof=[]
 for n in(0,85,*range(67,85),93,94):
  ims=[arc.composite(n,mask)[0].crop((112,120,208,192))for mask in(0,15)for arc in(a,b)];uris=[];hashes=[]
  for j,im in enumerate(ims):
   im.save(o/f'ref_{n:03}_{j}.png');buf=io.BytesIO();im.save(buf,format='PNG');uris.append('data:image/png;base64,'+base64.b64encode(buf.getvalue()).decode());z=np.array(im);z[z[:,:,3]==0]=0;hashes.append(sha(z.tobytes()))
  data[str(n)]=uris;proof.append({'ref':n,'canvas_rgba_sha256':hashes})
 anim={q['id']:[{'ref':s['frame_ref'],'calls':s['duration_calls']}for s in q['steps']]for q in p['animations']if q['id']in(16,17,18,19)}
 cases={'대시 반복71/75/73':[{'ref':n,'calls':1}for n in(71,75,73)],'대시 종료→대기':anim[17][:4]+[{'ref':0,'calls':18}],'시작→반복':anim[16][2:8]+[{'ref':n,'calls':1}for n in(71,75,73)],'공중 전환93/94':anim[18][:3]+[{'ref':n,'calls':1}for n in(71,75,73)]}
 for name,seq in list(cases.items()):cases[name+' · 사격 치환']=[{'ref':q['ref']+1 if 67<=q['ref']<=83 and q['ref']%2 else 85 if q['ref']==0 else q['ref'],'calls':q['calls']}for q in seq]
 html='''<!doctype html><meta charset="utf-8"><title>나나 새 대시 네이티브 검토</title><style>body{font:16px sans-serif;color:#eee;background:#20242a}canvas{background:#b6c0c7;image-rendering:pixelated;margin:5px}section{display:flex;gap:12px}button,select{font:inherit;margin:7px}small{display:block;max-width:1100px;line-height:1.6}</style><h1>나나 대시: 기본 전/후 · 포스 전/후</h1><small>패킹한 ARC를 다시 디코드한 그림입니다. 원본 애니메이션 참조·유지 호출 수를 60호출/초로 표시합니다. 게임 입력/충돌/이벤트 분기 실행은 아닙니다. 사격 치환은 해당 짝의 사격 그림을 같은 시간표로 비교하는 도구입니다. 93/94는 서로 다른 공중 전환이며 사격 쌍이 아닙니다.</small><select id="which"></select><select id="speed"><option value="1">원속도 가정</option><option value="0.25" selected>0.25배 검토</option></select><button id="play">일시정지</button><button id="next">다음 자세</button><span id="status"></span><section>CANVASES</section><section>BIGCANVASES</section><script>const DATA=DATAJSON,CASES=CASEJSON;let images={},sequence=[],index=0,elapsed=0,run=true,last=0,draws=0;const ready=Promise.all(Object.entries(DATA).map(async([k,v])=>images[k]=await Promise.all(v.map(u=>new Promise(resolve=>{let im=new Image;im.onload=()=>resolve(im);im.src=u})))));for(const k of Object.keys(CASES)){let o=document.createElement('option');o.value=k;o.textContent=k;which.append(o)}function draw(){let q=sequence[index];document.getElementById('status').textContent='ref '+q.ref+' / '+q.calls+'호출';for(let j=0;j<4;j++)for(let prefix of ['small','big']){let c=document.getElementById(prefix+j),ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(images[q.ref][j],0,0,c.width,c.height)}draws++}function selectCase(k){sequence=CASES[k];index=elapsed=0;which.value=k;draw()}function step(){index=(index+1)%sequence.length;draw()}function setRun(v){run=v;play.textContent=run?'일시정지':'재생'}window.review={ready,setCase:selectCase,selectRef(n){setRun(false);sequence=[{ref:n,calls:1}];index=0;draw()},pause(){setRun(false)},play(){setRun(true)},step,state:()=>({run,index,ref:sequence[index].ref,draws}),cases:CASES};which.onchange=()=>selectCase(which.value);play.onclick=()=>setRun(!run);next.onclick=()=>{setRun(false);step()};function tick(t){if(!last)last=t;const dt=Math.min(t-last,250);last=t;if(run){elapsed+=dt*Number(speed.value)*60/1000;while(elapsed>=sequence[index].calls){elapsed-=sequence[index].calls;step()}}requestAnimationFrame(tick)}ready.then(()=>{selectCase(Object.keys(CASES)[0]);requestAnimationFrame(tick)})</script>'''
 html=html.replace('BIGCANVASES',''.join(f'<canvas id="big{j}" width="384" height="288"></canvas>'for j in range(4))).replace('CANVASES',''.join(f'<canvas id="small{j}" width="96" height="72"></canvas>'for j in range(4))).replace('DATAJSON',json.dumps(data,separators=(',',':'))).replace('CASEJSON',json.dumps(cases,ensure_ascii=False,separators=(',',':')));(o/'REVIEW.html').write_text(html,'utf8');write(o/'manifest.json',{'source_arc_sha256':sha(a.data),'candidate_arc_sha256':sha(b.data),'frames':proof,'cases':cases,'html_sha256':digest(o/'REVIEW.html'),'runtime_verified':False,'clock_assumption':'60 calls/second; original table counts, no game control flow'});print(str(o))
if __name__=='__main__':main()
